INSERT INTO `knowledge_chunk` VALUES (192,5,0,'1. 产量预测逻辑','2025-08-21 14:36:16'),(193,5,1,'- 产量计算基础：','2025-08-21 14:36:16'),(194,5,2,'   - 产量 ≈ 簇内金针菇数量 × 平均大小 × 成熟率系数','2025-08-21 14:36:16'),(195,5,3,'   - 成熟率系数由「成熟 / 半熟 / 未熟比例」决定。','2025-08-21 14:36:16'),(196,5,4,'- 分阶段产量：','2025-08-21 14:36:16'),(197,5,5,'   - 已成熟果：当前可采收量。','2025-08-21 14:36:16'),(198,5,6,'   - 半成熟果：预计 1–3 天成熟，产量需根据温度、光照条件进行修正。','2025-08-21 14:36:16'),(199,5,7,'   - 未成熟果：预计 3–7 天成熟，产量受营养供给和病虫害影响较大。','2025-08-21 14:36:16'),(200,5,8,'2. 影响因子（产量修正系数）','2025-08-21 14:36:16'),(201,5,9,'- 环境因子：','2025-08-21 14:36:16'),(202,5,10,'   - 光照不足：果实重量减少 10–20%。','2025-08-21 14:36:16'),(203,5,11,'   - 夜间温度过高（>25℃）：影响糖分积累，果实变小。','2025-08-21 14:36:16'),(204,5,12,'   - 湿度过大：易发生灰霉病，产量减少 15–30%。','2025-08-21 14:36:16'),(205,5,13,'- 养分因子：','2025-08-21 14:36:16'),(206,5,14,'   - 氮肥过量→植株旺长，果实变小，产量下降。','2025-08-21 14:36:16'),(207,5,15,'   - 钾肥、钙肥充足→果实饱满，硬度提高，商品率提升 15–20%。','2025-08-21 14:36:16'),(208,5,16,'- 病虫害因子：','2025-08-21 14:36:16'),(209,5,17,'   - 炭疽病果腐：直接损失产量。','2025-08-21 14:36:16'),(210,5,18,'   - 白粉病：降低光合效率，果实变小。','2025-08-21 14:36:16'),(211,5,19,'   - 灰霉病：采收前果实腐烂，产量损失显著。','2025-08-21 14:36:16'),(212,5,20,'3. 环境与产量关系','2025-08-21 14:36:16'),(213,5,21,'- 空气温度','2025-08-21 14:36:16'),(214,5,22,'   - 适宜范围：18–25℃。','2025-08-21 14:36:16'),(215,5,23,'   - <15℃：果实膨大慢，产量下降。','2025-08-21 14:36:16'),(216,5,24,'   - «30℃：光合作用受抑制，果实畸形率上升。»','2025-08-21 14:36:16'),(217,5,25,'- 空气湿度','2025-08-21 14:36:16'),(218,5,26,'   - 适宜范围：60–75%。','2025-08-21 14:36:16'),(219,5,27,'   - «85%：灰霉病、白粉病风险高。»','2025-08-21 14:36:16'),(220,5,28,'   - <40%：花粉活力下降，坐果率低。','2025-08-21 14:36:16'),(221,5,29,'- 光照强度','2025-08-21 14:36:16'),(222,5,30,'   - 适宜范围：30,000–50,000 Lux。','2025-08-21 14:36:16'),(223,5,31,'   - 光照不足→果实变小、糖度降低。','2025-08-21 14:36:16'),(224,5,32,'- 二氧化碳','2025-08-21 14:36:16'),(225,5,33,'   - 适宜浓度：800–1200 ppm。','2025-08-21 14:36:16'),(226,5,34,'   - <400 ppm：光合作用不足，产量下降 10–20%。','2025-08-21 14:36:16'),(227,5,35,'4. 土壤与产量关系','2025-08-21 14:36:16'),(228,5,36,'- 土壤温度','2025-08-21 14:36:16'),(229,5,37,'   - 适宜范围：15–25℃。','2025-08-21 14:36:16'),(230,5,38,'   - <10℃：根系活力差。','2025-08-21 14:36:16'),(231,5,39,'   - «30℃：根系早衰。»','2025-08-21 14:36:16'),(232,5,40,'- 土壤湿度','2025-08-21 14:36:16'),(233,5,41,'   - 适宜范围：60–70%。','2025-08-21 14:36:16'),(234,5,42,'   - «80%：根系缺氧，易烂根。»','2025-08-21 14:36:16'),(235,5,43,'   - <40%：果实膨大不足。','2025-08-21 14:36:16'),(236,5,44,'- 电导率 (EC)','2025-08-21 14:36:16'),(237,5,45,'   - 适宜值：0.8–1.2 mS/cm。','2025-08-21 14:36:16'),(238,5,46,'   - 过高：盐害，影响吸收。','2025-08-21 14:36:16'),(239,5,47,'- pH','2025-08-21 14:36:16'),(240,5,48,'   - 适宜范围：5.5–6.5。','2025-08-21 14:36:16'),(241,5,49,'   - «7.0：铁、锰缺乏。»','2025-08-21 14:36:16'),(242,5,50,'   - <5.0：根系活力下降。','2025-08-21 14:36:16'),(243,5,51,'- 氮 (N)','2025-08-21 14:36:16'),(244,5,52,'   - 过量：徒长，果小。','2025-08-21 14:36:16'),(245,5,53,'   - 缺乏：叶片发黄，产量下降。','2025-08-21 14:36:16'),(246,5,54,'- 磷 (P)','2025-08-21 14:36:16'),(247,5,55,'   - 促进根系和开花。缺乏→花少果少。','2025-08-21 14:36:16'),(248,5,56,'- 钾 (K)','2025-08-21 14:36:16'),(249,5,57,'   - 促进果实膨大与糖分积累。缺乏→果实硬度低、糖度下降。','2025-08-21 14:36:16'),(250,5,58,'5. 专家建议（产量管理）','2025-08-21 14:36:16'),(251,5,59,'- 采收管理：','2025-08-21 14:36:16'),(252,5,60,'   - 已成熟果：优先采摘，防止过熟。','2025-08-21 14:36:16'),(253,5,61,'   - 半成熟果：注意天气变化，连续阴雨需提前采收。','2025-08-21 14:36:16'),(254,5,62,'   - 未成熟果：保持光照与养分，避免积水。','2025-08-21 14:36:16'),(255,5,63,'- 养分补充：','2025-08-21 14:36:16'),(256,5,64,'   - 膨果期补充钾、钙肥，避免裂果。','2025-08-21 14:36:16'),(257,5,65,'   - 避免后期氮肥过量。','2025-08-21 14:36:16'),(258,5,66,'- 病害预防：','2025-08-21 14:36:16'),(259,5,67,'   - 产量预测需结合病害风险评估。','2025-08-21 14:36:16'),(260,5,68,'   - 在高湿环境下，需提前 2–3 天进行防病喷药。','2025-08-21 14:36:16'),(261,5,69,'根据环境与土壤条件，修正产量预测值：','2025-08-21 14:36:16'),(262,5,70,'- 环境或养分超出适宜范围时，预估产量需降低 10–30%。','2025-08-21 14:36:16'),(263,5,71,'- 条件适宜时，预估产量可上调 5–15%。','2025-08-21 14:36:16'),(264,5,72,'采收时机需结合土壤湿度、温度，避免雨后立即采收。','2025-08-21 14:36:16'),(276,10,0,'1. Angular Leafspot（角斑病）','2025-08-21 20:59:47'),(277,10,1,'- 病原与传播：由 Xanthomonas fragariae 引起，细菌性病害，主要通过雨水、灌溉水传播。','2025-08-21 20:59:47'),(278,10,2,'- 症状：叶片出现水浸状小斑点，逐渐发展为褐色坏死斑，严重时叶片枯死。','2025-08-21 20:59:48'),(279,10,3,'- 环境与诱发条件：','2025-08-21 20:59:48'),(280,10,4,'   - 低温高湿（15–20℃）时易发；','2025-08-21 20:59:48'),(281,10,5,'   - 高湿度环境（空气湿度 > 80%、土壤湿度过高）会加重病害。','2025-08-21 20:59:48'),(282,10,6,'- 防治措施：','2025-08-21 20:59:49'),(283,10,7,'   - 物理：增加行距以减少叶面湿度，采用滴灌代替喷灌，避免叶面长时间潮湿。','2025-08-21 20:59:49'),(284,10,8,'   - 药剂：铜制剂、链霉素交替使用，防止病菌产生耐药性。','2025-08-21 20:59:49'),(285,10,9,'   - 管理：清除病残体，避免使用带病苗，减少病源基数。','2025-08-21 20:59:49'),(286,10,10,'   - 外部环境调控：降低棚内湿度，改善通风条件。','2025-08-21 20:59:49'),(287,10,11,'   - 土壤管理：避免过度灌水，保持土壤湿度在 60–70%。','2025-08-21 20:59:50'),(288,10,12,'   - 营养调控：氮肥过多易加重病害，需减少氮肥施用量。','2025-08-21 20:59:50'),(289,10,13,'2. Anthracnose Fruit Rot（炭疽病果腐）','2025-08-21 20:59:50'),(290,10,14,'- 病原与传播：由 Colletotrichum acutatum 引起，高温高湿条件下快速传播。','2025-08-21 20:59:50'),(291,10,15,'- 症状：果实出现黑色凹陷病斑，湿度大时病斑上长出粉红色黏孢子团。','2025-08-21 20:59:50'),(292,10,16,'- 危害：采前采后均可发病，采后贮藏期易腐烂，导致严重产量损失。','2025-08-21 20:59:50'),(293,10,17,'- 环境与诱发条件：高温高湿（温度 > 28℃、空气湿度 > 80%）、氮肥过多时病害易爆发。','2025-08-21 20:59:51'),(294,10,18,'- 防治措施：','2025-08-21 20:59:51'),(295,10,19,'   - 物理：避免果实接触地面，采后采用低温冷链贮藏，抑制病菌繁殖。','2025-08-21 20:59:51'),(296,10,20,'   - 药剂：吡唑醚菌酯、苯醚甲环唑、啶酰菌胺交替使用，降低耐药风险。','2025-08-21 20:59:51'),(297,10,21,'   - 管理：及时清除病果，避免连作，减少病菌积累。','2025-08-21 20:59:52'),(298,10,22,'   - 外部环境调控：改善通风条件，保持空气湿度 < 75%。','2025-08-21 20:59:52'),(299,10,23,'   - 土壤管理：避免积水，控制土壤湿度在 60–70%。','2025-08-21 20:59:52'),(300,10,24,'   - 营养调控：减少氮肥施用量，补充钾肥以提高果实抗性。','2025-08-21 20:59:52'),(301,10,25,'3. Gray Mold（灰霉病）','2025-08-21 20:59:53'),(302,10,26,'- 病原与传播：由 Botrytis cinerea 引起，花器及幼果期感染最重，通过空气传播孢子。','2025-08-21 20:59:53'),(303,10,27,'- 症状：果实表面出现灰色霉层，触碰即掉落孢子粉，后期果实腐烂。','2025-08-21 20:59:53'),(304,10,28,'- 环境与诱发条件：','2025-08-21 20:59:53'),(305,10,29,'   - 温度 15–20℃、相对湿度 > 85% 时最易爆发；','2025-08-21 20:59:54'),(306,10,30,'   - 光照不足、果实表面长时间潮湿会加重病害。','2025-08-21 20:59:54'),(307,10,31,'- 防治措施：','2025-08-21 20:59:54'),(308,10,32,'   - 物理：加强通风以降低棚内湿度，避免果实相互挤压，减少接触传播。','2025-08-21 20:59:54'),(309,10,33,'   - 药剂：腐霉利、异菌脲、嘧霉胺轮换使用，避免耐药性产生。','2025-08-21 20:59:54'),(310,10,34,'   - 管理：及时采收病果，减少病源基数，降低扩散风险。','2025-08-21 20:59:54'),(311,10,35,'   - 外部环境调控：加大通风量，避免棚内结露，减少高湿环境。','2025-08-21 20:59:55'),(312,10,36,'   - 土壤管理：适度控水，避免叶片和果实接触湿土，降低感染概率。','2025-08-21 20:59:55'),(313,10,37,'   - 营养调控：适量补钙，提高果实硬度，减少腐烂风险。','2025-08-21 20:59:55'),(314,10,38,'4. Leaf Spot（叶斑病）','2025-08-21 20:59:55'),(315,10,39,'- 病原与传播：由 Mycosphaerella fragariae 引起，通过气流或雨水传播。','2025-08-21 20:59:56'),(316,10,40,'- 症状：叶片出现褐色小圆斑，边缘清晰，中部呈灰白色，影响光合作用。','2025-08-21 20:59:56'),(317,10,41,'- 环境与诱发条件：温度 15–25℃、空气湿度 70–80% 时易发病；土壤 pH<5 时病害加重。','2025-08-21 20:59:56'),(318,10,42,'- 防治措施：','2025-08-21 20:59:56'),(319,10,43,'   - 物理：减少叶片潮湿时间，避免密植，改善植株间通风透光性。','2025-08-21 20:59:56'),(320,10,44,'   - 药剂：代森锰锌、氯溴异氰尿酸喷施防治。','2025-08-21 20:59:57'),(321,10,45,'   - 管理：选择抗病品种，注意轮作，减少病菌积累。','2025-08-21 20:59:57'),(322,10,46,'   - 外部环境调控：及时摘除病叶，降低田间病菌密度。','2025-08-21 20:59:57'),(323,10,47,'   - 土壤管理：调节土壤 pH 至 5.5–6.5，创造不适宜病菌繁殖的环境。','2025-08-21 20:59:57'),(324,10,48,'   - 营养调控：氮肥过多会加重病害，需控制氮肥施用量。','2025-08-21 20:59:58'),(325,10,49,'5. Powdery Mildew Fruit（果实白粉病）','2025-08-21 20:59:58'),(326,10,50,'- 病原与传播：由 Podosphaera aphanis 引起，通过气流传播孢子。','2025-08-21 20:59:58'),(327,10,51,'- 症状：果实表面覆盖白色粉层，导致果实变形，商品率显著下降。','2025-08-21 20:59:58'),(328,10,52,'- 环境与诱发条件：','2025-08-21 20:59:58'),(329,10,53,'   - 温暖干燥（20–25℃）、通风不良的温室环境易发；','2025-08-21 20:59:59'),(330,10,54,'   - 氮肥过多会加重病害。','2025-08-21 20:59:59'),(331,10,55,'- 防治措施：','2025-08-21 20:59:59'),(332,10,56,'   - 物理：改善通风条件，避免湿热闷棚环境。','2025-08-21 20:59:59'),(333,10,57,'   - 药剂：三唑类（戊唑醇）、硫制剂交替使用，提高防治效果。','2025-08-21 21:00:00'),(334,10,58,'   - 管理：选用无病苗木，避免带病栽培，减少初始病源。','2025-08-21 21:00:00'),(335,10,59,'   - 外部环境调控：增加空气流通，降低局部湿度，抑制孢子萌发。','2025-08-21 21:00:00'),(336,10,60,'   - 土壤管理：控制氮肥用量，保持土壤电导率（EC）<1.2 mS/cm，避免盐害影响植株抗性。','2025-08-21 21:00:00')