--
-- Table structure for table `monitor_record`
--

DROP TABLE IF EXISTS `monitor_record`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `monitor_record` (
  `record_id` int NOT NULL AUTO_INCREMENT COMMENT '记录编号',
  `address_id` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '设备地址（485传感器地址）',
  `air_temperature` double DEFAULT NULL COMMENT '空气温度（。C）',
  `air_humidity` double DEFAULT NULL COMMENT '空气湿度（%）',
  `light_lux` int DEFAULT NULL COMMENT '光照强度（Lux）',
  `air_co2` int DEFAULT NULL COMMENT '二氧化碳（ppm）',
  `soil_temperature` double DEFAULT NULL COMMENT '土壤温度（。C）',
  `soil_humidity` double DEFAULT NULL COMMENT '土壤湿度（%）',
  `soil_conductivity` int DEFAULT NULL COMMENT '电导率（us/cm）',
  `soil_PH` double DEFAULT NULL COMMENT '土壤PH值',
  `soil_N` int DEFAULT NULL COMMENT '氮（mg/kg）',
  `soil_P` int DEFAULT NULL COMMENT '磷（mg/kg）',
  `soil_K` int DEFAULT NULL COMMENT '钾（mg/kg）',
  `create_date` datetime DEFAULT NULL COMMENT '记录时间',
  `plant_id` int DEFAULT NULL COMMENT '植物ID',
  `area_id` int DEFAULT NULL COMMENT '场地ID',
  `user_id` int NOT NULL COMMENT '用户id',
  `create_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '创建人',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  `update_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '更新人',
  `del_flag` int DEFAULT NULL COMMENT '是否删除：0，未删除，1，删除',
  PRIMARY KEY (`record_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4797 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `monitor_record`
--

